// relocateAllSuccess reports whether every chain re-apply in a relocate report
// succeeded (drives the top-level alert class).
func relocateAllSuccess(report *chain.RelocateReport) bool {
	if report == nil || len(report.Chains) == 0 {
		return false
	}
	for _, c := range report.Chains {
		if !c.Success {
			return false
		}
	}
	return true
}

func nodeListStr(nodes []model.ChainNode) string {
	s := ""
	for i, n := range nodes {
		if i > 0 {
			s += ", "
		}
		s += n.ID
	}
	return s
}

func moreNodesStr(nodes []model.ChainNode) string {
	if len(nodes) <= 2 {
		return ""
	}
	return fmt.Sprintf("%d", len(nodes)-2)
}

func chainHasNode(c *model.Chain, nodeID string) bool {
	for _, n := range c.Nodes {
		if n.ID == nodeID {
			return true
		}
	}
	return false
}

// isChainEntry reports whether nodeID is a user-facing entry for the chain.
// Honors the explicit ChainNode.Role field; falls back to "index 0 is entry"
// for legacy chains with no explicit role (matches resolveChainRoles).
func isChainEntry(c *model.Chain, nodeID string) bool {
	for i, n := range c.Nodes {
		if n.ID == nodeID {
			return n.Role == model.NodeRoleEntry || (n.Role == "" && i == 0)
		}
	}
	return false
}

func alertClass(success bool) string {
	if success {
		return "alert-success"
	}
	return "alert-error"
}

